; SRC/EXTERNAL/COMP/COMP.S
; SPDX-LICENSE-IDENTIFIER: MIT
; COPYRIGHT (C) 2026 COMMAND64 PROJECT CONTRIBUTORS
;
; COMP: EXTERNAL RAW BYTE-STREAM FILE COMPARISON UTILITY.
; PHASE 1 SCOPE: STRICT "COMP FILE1 FILE2" SYNTAX, NO OPTIONS, RAW BYTES
; REGARDLESS OF FILE TYPE, 24-BIT HEX OFFSETS, AND 10 DISPLAYED MISMATCHES.

; NATIVE-CASM SOURCE IS UPPERCASE ASCII THROUGHOUT BECAUSE CC1541 COPIES HOST
; BYTES TO SEQ FILES VERBATIM. CONSTANTS ARE INLINE SO ZERO-PAGE-VALUED NAMES
; SELECT ZERO-PAGE ADDRESSING UNDER CASM 0.6.2.

; C64 KERNAL JUMP TABLE.
KERNALCHROUT = $FFD2

; COMMAND64 API ENTRY AND SELECTORS.
OS_API         = $1000
DOS_PRINT_STR  = $09
DOS_OPEN_FILE  = $3D
DOS_CLOSE_FILE = $3E
DOS_READ_FILE  = $3F
DOS_EXIT       = $4C

; COMMAND64 GLOBALS AND SHARED ZERO-PAGE SCRATCH.
COMMANDBUFFER = $033C
PARSEPOS      = $63
HEXVALLO      = $66
HEXVALHI      = $67
FILEHANDLE    = $6D
PRINTPTRLO    = $FB
PRINTPTRHI    = $FC

PETCR = $0D

; APP-PRIVATE ZERO-PAGE SCRATCH ($70-$8F IS RESERVED FOR EXTERNAL PROGRAMS).
FILE1HANDLE   = $70
FILE2HANDLE   = $71
ARGSTART      = $72
OFFSETLO      = $73
OFFSETMID     = $74
OFFSETHI      = $75
MISMATCHCOUNT = $76
READ1COUNT    = $77
READ2COUNT    = $78
COMPARECOUNT  = $79
INDEXSAVE     = $7A
BYTE1SAVE     = $7B
BYTE2SAVE     = $7C
STOPFLAG      = $7D
SIZEDIFFFLAG  = $7E
DESTINDEX     = $7F

FILENAME_MAX   = 39
CHUNK_SIZE     = 64
MAX_MISMATCHES = 10

PARSE_OK       = 0
PARSE_MISSING  = 1
PARSE_EXTRA    = 2
PARSE_OPTION   = 3
PARSE_TOO_LONG = 4

; ---------------------------------------------------------------------------
; ENTRY POINT
; ---------------------------------------------------------------------------
START:
    LDA #$FF
    STA FILE1HANDLE
    STA FILE2HANDLE
    LDA #0
    STA OFFSETLO
    STA OFFSETMID
    STA OFFSETHI
    STA MISMATCHCOUNT
    STA STOPFLAG
    STA SIZEDIFFFLAG

    JSR PARSEARGS
    BCC @ARGSOK
    JSR PRINTPARSEERROR
    JMP @EXIT

@ARGSOK:
    JSR OPENFILES
    BCC @FILESOPEN
    JMP @CLOSEANDEXIT

@FILESOPEN:
    JSR COMPAREFILES
    JSR PRINTSUMMARY
    JMP @CLOSEANDEXIT

@CLOSEANDEXIT:
    JSR CLOSEFILES
@EXIT:
    LDA #DOS_EXIT
    JSR OS_API

; ---------------------------------------------------------------------------
; PARSEARGS
; PARSES COMMANDBUFFER AFTER THE EXTERNAL COMMAND TOKEN.
; OUTPUT: CARRY CLEAR ON SUCCESS, FILE1BUF/FILE2BUF NULL-TERMINATED.
;         CARRY SET AND A = PARSE_* ON ERROR.
; ---------------------------------------------------------------------------
PARSEARGS:
    LDY PARSEPOS

@PASKIPTOKEN:
    LDA COMMANDBUFFER, Y
    BEQ @PAMISSING
    CMP #' '
    BEQ @PAAFTERTOKEN
    INY
    JMP @PASKIPTOKEN

@PAAFTERTOKEN:
    JSR SKIPSPACES
    LDA COMMANDBUFFER, Y
    BEQ @PAMISSING
    CMP #'/'
    BEQ @PAOPTION

    LDX #<FILE1BUF
    STX PRINTPTRLO
    LDX #>FILE1BUF
    STX PRINTPTRHI
    JSR PARSETOKEN
    BCS @PAERROR

    JSR SKIPSPACES
    LDA COMMANDBUFFER, Y
    BEQ @PAMISSING
    CMP #'/'
    BEQ @PAOPTION

    LDX #<FILE2BUF
    STX PRINTPTRLO
    LDX #>FILE2BUF
    STX PRINTPTRHI
    JSR PARSETOKEN
    BCS @PAERROR

    JSR SKIPSPACES
    LDA COMMANDBUFFER, Y
    BNE @PAEXTRA

    CLC
    LDA #PARSE_OK
    RTS

@PAMISSING:
    SEC
    LDA #PARSE_MISSING
    RTS
@PAEXTRA:
    SEC
    LDA #PARSE_EXTRA
    RTS
@PAOPTION:
    SEC
    LDA #PARSE_OPTION
    RTS
@PAERROR:
    RTS

; INPUT: Y = COMMANDBUFFER TOKEN START, PRINTPTRLO/HI = DESTINATION BUFFER.
; OUTPUT: Y = FIRST DELIMITER AFTER TOKEN, CARRY STATUS.
PARSETOKEN:
    STY ARGSTART
    LDA #0
    STA DESTINDEX
@PTLOOP:
    LDY ARGSTART
    LDA COMMANDBUFFER, Y
    BEQ @PTDONE
    CMP #' '
    BEQ @PTDONE
    LDX DESTINDEX
    CPX #FILENAME_MAX
    BCS @PTTOOLONG
    LDY DESTINDEX
    STA (PRINTPTRLO), Y
    INC DESTINDEX
    INC ARGSTART
    JMP @PTLOOP

@PTDONE:
    LDA DESTINDEX
    BEQ @PTMISSING
    TAY
    LDA #0
    STA (PRINTPTRLO), Y
    LDY ARGSTART
    CLC
    LDA #PARSE_OK
    RTS

@PTMISSING:
    SEC
    LDA #PARSE_MISSING
    RTS
@PTTOOLONG:
    SEC
    LDA #PARSE_TOO_LONG
    RTS

SKIPSPACES:
    LDA COMMANDBUFFER, Y
    CMP #' '
    BNE @DONE
    INY
    JMP SKIPSPACES
@DONE:
    RTS

PRINTPARSEERROR:
    CMP #PARSE_OPTION
    BEQ @OPTION
    CMP #PARSE_EXTRA
    BEQ @EXTRA
    CMP #PARSE_TOO_LONG
    BEQ @TOOLONG
    JMP PRINTUSAGE
@OPTION:
    LDX #<MSGUNKNOWNOPTION
    LDY #>MSGUNKNOWNOPTION
    LDA #DOS_PRINT_STR
    JSR OS_API
    JMP PRINTUSAGE
@EXTRA:
    LDX #<MSGTOOMANYARGS
    LDY #>MSGTOOMANYARGS
    LDA #DOS_PRINT_STR
    JSR OS_API
    JMP PRINTUSAGE
@TOOLONG:
    LDX #<MSGNAMETOOLONG
    LDY #>MSGNAMETOOLONG
    LDA #DOS_PRINT_STR
    JSR OS_API
PRINTUSAGE:
    LDX #<MSGUSAGE
    LDY #>MSGUSAGE
    LDA #DOS_PRINT_STR
    JSR OS_API
    RTS

; ---------------------------------------------------------------------------
; FILE OPEN/CLOSE
; ---------------------------------------------------------------------------
OPENFILES:
    LDA #0
    STA HEXVALLO
    LDX #<FILE1BUF
    LDY #>FILE1BUF
    LDA #DOS_OPEN_FILE
    JSR OS_API
    BCC @FILE1OK
    JSR PRINTOPENERROR
    SEC
    RTS
@FILE1OK:
    STA FILE1HANDLE

    LDA #0
    STA HEXVALLO
    LDX #<FILE2BUF
    LDY #>FILE2BUF
    LDA #DOS_OPEN_FILE
    JSR OS_API
    BCC @FILE2OK
    JSR PRINTOPENERROR
    SEC
    RTS
@FILE2OK:
    STA FILE2HANDLE
    CLC
    RTS

CLOSEFILES:
    LDA FILE2HANDLE
    CMP #$FF
    BEQ @SKIP2
    STA FILEHANDLE
    LDA #DOS_CLOSE_FILE
    JSR OS_API
    LDA #$FF
    STA FILE2HANDLE
@SKIP2:
    LDA FILE1HANDLE
    CMP #$FF
    BEQ @DONE
    STA FILEHANDLE
    LDA #DOS_CLOSE_FILE
    JSR OS_API
    LDA #$FF
    STA FILE1HANDLE
@DONE:
    RTS

PRINTOPENERROR:
    LDX #<MSGOPENERROR
    LDY #>MSGOPENERROR
    LDA #DOS_PRINT_STR
    JSR OS_API
    RTS

; ---------------------------------------------------------------------------
; COMPARE LOOP
; ---------------------------------------------------------------------------
COMPAREFILES:
@LOOP:
    JSR READFILE1
    BCC @READ1OK
    JMP CFREADERROR
@READ1OK:
    JSR READFILE2
    BCC @READ2OK
    JMP CFREADERROR
@READ2OK:
    JSR SETCOMPARECOUNT
    JSR COMPAREOVERLAP
    LDA STOPFLAG
    BNE CMPDONE

    LDA READ1COUNT
    CMP READ2COUNT
    BEQ @COUNTSEQUAL
    LDA #1
    STA SIZEDIFFFLAG
    LDX #<MSGSIZEDIFF
    LDY #>MSGSIZEDIFF
    LDA #DOS_PRINT_STR
    JSR OS_API
    JMP CMPDONE

@COUNTSEQUAL:
    LDA READ1COUNT
    BEQ CMPDONE
    CMP #CHUNK_SIZE
    BEQ @LOOP
    ; EQUAL SHORT READS MEAN BOTH FILES ENDED AFTER THE SAME FINAL CHUNK.
CMPDONE:
    RTS

CFREADERROR:
    LDX #<MSGREADERROR
    LDY #>MSGREADERROR
    LDA #DOS_PRINT_STR
    JSR OS_API
    LDA #1
    STA STOPFLAG
    RTS

READFILE1:
    LDA FILE1HANDLE
    STA FILEHANDLE
    LDX #<BUF1
    LDY #>BUF1
    JSR READCHUNK
    STA READ1COUNT
    RTS

READFILE2:
    LDA FILE2HANDLE
    STA FILEHANDLE
    LDX #<BUF2
    LDY #>BUF2
    JSR READCHUNK
    STA READ2COUNT
    RTS

; INPUT: FILEHANDLE, X/Y = BUFFER.
; OUTPUT: A = BYTES READ, CARRY CLEAR ON SUCCESS/EOF, CARRY SET ON READ ERROR.
READCHUNK:
    LDA #CHUNK_SIZE
    STA HEXVALLO
    LDA #0
    STA HEXVALHI
    LDA #DOS_READ_FILE
    JSR OS_API
    BCC @OK
    LDA HEXVALLO
    ORA HEXVALHI
    BEQ @EOF               ; READ-PAST-EOF COMPATIBILITY PATH
    SEC
    LDA HEXVALLO
    RTS
@EOF:
    CLC
    LDA #0
    RTS
@OK:
    LDA HEXVALLO
    CLC
    RTS

SETCOMPARECOUNT:
    LDA READ1COUNT
    CMP READ2COUNT
    BCC @USEA
    LDA READ2COUNT
@USEA:
    STA COMPARECOUNT
    RTS

COMPAREOVERLAP:
    LDX #0
@LOOP:
    CPX COMPARECOUNT
    BEQ @DONE
    LDA BUF1, X
    CMP BUF2, X
    BEQ @NEXT
    STA BYTE1SAVE
    LDA BUF2, X
    STA BYTE2SAVE
    STX INDEXSAVE
    JSR REPORTMISMATCH
    LDX INDEXSAVE
    LDA STOPFLAG
    BNE @DONE
@NEXT:
    JSR INCOFFSET24
    INX
    JMP @LOOP
@DONE:
    RTS

INCOFFSET24:
    INC OFFSETLO
    BNE @DONE
    INC OFFSETMID
    BNE @DONE
    INC OFFSETHI
@DONE:
    RTS

REPORTMISMATCH:
    LDX #<MSGCOMPAREAT
    LDY #>MSGCOMPAREAT
    LDA #DOS_PRINT_STR
    JSR OS_API
    LDA OFFSETHI
    JSR PRINTHEX8
    LDA OFFSETMID
    JSR PRINTHEX8
    LDA OFFSETLO
    JSR PRINTHEX8
    LDX #<MSGCOLONDOLLAR
    LDY #>MSGCOLONDOLLAR
    LDA #DOS_PRINT_STR
    JSR OS_API
    LDA BYTE1SAVE
    JSR PRINTHEX8
    LDX #<MSGSPACEDOLLAR
    LDY #>MSGSPACEDOLLAR
    LDA #DOS_PRINT_STR
    JSR OS_API
    LDA BYTE2SAVE
    JSR PRINTHEX8
    LDA #PETCR
    JSR KERNALCHROUT

    INC MISMATCHCOUNT
    LDA MISMATCHCOUNT
    CMP #MAX_MISMATCHES
    BCC @DONE
    LDA #1
    STA STOPFLAG
    LDX #<MSGSTOP
    LDY #>MSGSTOP
    LDA #DOS_PRINT_STR
    JSR OS_API
@DONE:
    RTS

PRINTSUMMARY:
    LDA STOPFLAG
    BNE @DONE
    LDA MISMATCHCOUNT
    BNE @DONE
    LDA SIZEDIFFFLAG
    BNE @DONE
    LDX #<MSGOK
    LDY #>MSGOK
    LDA #DOS_PRINT_STR
    JSR OS_API
@DONE:
    RTS

PRINTHEX8:
    PHA
    LSR A
    LSR A
    LSR A
    LSR A
    JSR @NIBBLE
    PLA
    AND #$0F
@NIBBLE:
    CMP #10
    BCC @DIGIT
    CLC
    ADC #7
@DIGIT:
    ADC #48
    JSR KERNALCHROUT
    RTS

; ---------------------------------------------------------------------------
; DATA
; ---------------------------------------------------------------------------
MSGUSAGE:
    .BYTE "USAGE: COMP FILE1 FILE2", PETCR, 0
MSGUNKNOWNOPTION:
    .BYTE "UNKNOWN OPTION", PETCR, 0
MSGTOOMANYARGS:
    .BYTE "TOO MANY ARGUMENTS", PETCR, 0
MSGNAMETOOLONG:
    .BYTE "FILE NAME TOO LONG", PETCR, 0
MSGOPENERROR:
    .BYTE "FILE OPEN ERROR", PETCR, 0
MSGREADERROR:
    .BYTE "READ ERROR", PETCR, 0
MSGCOMPAREAT:
    .BYTE "COMPARE ERROR AT $", 0
MSGCOLONDOLLAR:
    .BYTE ": $", 0
MSGSPACEDOLLAR:
    .BYTE " $", 0
MSGSTOP:
    .BYTE "10 MISMATCHES - STOPPING", PETCR, 0
MSGSIZEDIFF:
    .BYTE "FILES ARE DIFFERENT SIZES", PETCR, 0
MSGOK:
    .BYTE "FILES COMPARE OK", PETCR, 0

FILE1BUF:
    .RES FILENAME_MAX + 1, $00
FILE2BUF:
    .RES FILENAME_MAX + 1, $00
BUF1:
    .RES CHUNK_SIZE, $00
BUF2:
    .RES CHUNK_SIZE, $00
